L6_1 = "호오~ 그걸 받아 친 거야? 젊어서 그런가? 동체 시력이 대단한데?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "へえ～今のを打ち返したの？　若いからかしら、結構な動体視力ね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Ho-oh! You deflected that? I guess you're still young. You have great eyesight."
L5_1.m_Talk_ENG = L6_1
