L7_1 = "맞아. 맥크레디 가문의 워치가 없는 한, 이렇게 능력을 최소화하면서 싸울 수밖에 없거든."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そうよ。マクレディー家のウォッチがない限り、能力は最低限に抑えて戦うしかないの。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You're right. Without the MacCready family's Watch, I have to fight by minimizing my abilities."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不要怪我喔？因為沒有麥克蕾蒂家族的能量環，所以只能以最小的能力戰鬥。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "不要怪我哦？因为没有麦克雷迪家族的能量环，所以只能以最小的能力战斗。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "You're right. Without the MacCready family's Watch, I have to fight by minimizing my abilities."
