L25_1 = "就是在對方確信勝利的那一刻捅一刀。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "就是在对方确信胜利的那一刻捅一刀。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Go for the throat as soon as the opponent is sure of their victory."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Go for the throat as soon as the opponent is sure of their victory."
L24_1.m_Talk_FRA = L25_1
